mapper.select:
SELECT L.COLLECT_ID, L.BILL_ID, L.ORDER_ID, L.CUST_ID, C.CUST_NM, L.COLLECT_DT,
       L.COLLECT_AMT, L.COLLECT_METHOD, L.REG_USER_ID
FROM TB_COLLECT L
LEFT OUTER JOIN TB_CUSTOMER C ON C.CUST_ID = L.CUST_ID


        L.CUST_ID = #{custId}


        AND L.BILL_ID = #{billId}


        AND L.COLLECT_DT >= #{fromDt}


        AND L.COLLECT_DT <= #{toDt}


ORDER BY L.COLLECT_DT DESC, L.COLLECT_ID DESC

SELECT B.BILL_ID, B.ORDER_ID, B.CUST_ID, C.CUST_NM, B.BILL_DT, B.TOTAL_AMT, IFNULL(P.PAID_AMT, 0) AS PAID_AMT, B.TOTAL_AMT - IFNULL(P.PAID_AMT, 0) AS ARREARS_AMT, DATEDIFF(NOW(), B.BILL_DT) AS OVERDUE_DAYS FROM TB_BILL B INNER JOIN TB_CUSTOMER C ON C.CUST_ID = B.CUST_ID LEFT OUTER JOIN (SELECT BILL_ID, SUM(COLLECT_AMT) AS PAID_AMT FROM TB_COLLECT GROUP BY BILL_ID) P ON P.BILL_ID = B.BILL_ID WHERE B.ISSUE_STATUS = '10' AND B.TOTAL_AMT - IFNULL(P.PAID_AMT, 0) > 0
AND DATEDIFF(NOW(), B.BILL_DT) >= #{overdueDays}
AND B.CUST_ID = #{custId}
ORDER BY OVERDUE_DAYS DESC, B.BILL_ID
